from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize a list to store the extracted groups

    # Step 2: Identify and extract groups of nested parentheses
    start = 0
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            start = i
        elif paren_string[i] == ')':
            groups.append(paren_string[start:i+1])

    # Step 3: Separate the extracted groups into distinct strings
    distinct_groups = []
    for group in groups:
        distinct_group = ""
        for char in group:
            if char in ['(', ')']:
                distinct_group += char
        distinct_groups.append(distinct_group)

    # Step 4: Ensure the order of groups in the output matches the input order
    return distinct_groups

